        return 0

    from collections import defaultdict

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to detect shortest paths with negative weights
    # We will use it to detect if there is a negative cycle reachable from s
    # and to find the shortest path to t if no negative cycle is present

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n-1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] != float('inf') and dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in graph:
        for v, w in graph[u]:
            if dist[u] != float('inf') and dist[v] > dist[u] + w:
                # There is a negative cycle
                if t in graph or t == s:
                    return -1

    return dist[t] if dist[t] != float('inf') else -1

